"""Plain text absence notices for parents."""

import rosterkit.attendance


def absence_notice(*, student, marks):
    """Build a short notice listing the days the student was absent.

    Raises ValueError if any mark belongs to another student or if the
    marks contain no absences.
    """
    marks = list(marks)
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                'mark for student {} does not belong to {}'.format(
                    mark.student_id, student.student_id
                )
            )
    days = rosterkit.attendance.days_missed(marks)
    if not days:
        raise ValueError('no absences for student {}'.format(student.student_id))
    count = len(days)
    noun = 'day' if count == 1 else 'days'
    dates = ', '.join(day.isoformat() for day in days)
    return '{} {} missed {} {}: {}.'.format(
        student.first_name, student.last_name, count, noun, dates
    )
