import datetime
import unittest

import rosterkit.models
import rosterkit.notices


STUDENT = rosterkit.models.Student('7', 'Lopez', 'Ana', 'A')


def mark(student_id, month, day, status):
    return rosterkit.models.Mark(
        student_id, datetime.date(2026, month, day), status
    )


class AbsenceNoticeTests(unittest.TestCase):
    def test_when_absent_on_several_days_dates_are_in_order(self):
        marks = [
            mark('7', 9, 10, 'absent'),
            mark('7', 9, 2, 'absent'),
            mark('7', 9, 5, 'present'),
            mark('7', 9, 6, 'excused'),
        ]
        notice = rosterkit.notices.absence_notice(student=STUDENT, marks=marks)
        self.assertEqual(
            notice, 'Ana Lopez missed 2 days: 2026-09-02, 2026-09-10.'
        )

    def test_when_absent_once_day_is_singular(self):
        notice = rosterkit.notices.absence_notice(
            student=STUDENT, marks=[mark('7', 9, 2, 'absent')]
        )
        self.assertEqual(notice, 'Ana Lopez missed 1 day: 2026-09-02.')

    def test_when_a_mark_is_for_another_student_it_raises(self):
        marks = [mark('7', 9, 2, 'absent'), mark('8', 9, 3, 'absent')]
        with self.assertRaises(ValueError):
            rosterkit.notices.absence_notice(student=STUDENT, marks=marks)

    def test_when_there_are_no_absences_it_raises(self):
        marks = [mark('7', 9, 2, 'present'), mark('7', 9, 3, 'excused')]
        with self.assertRaises(ValueError):
            rosterkit.notices.absence_notice(student=STUDENT, marks=marks)

    def test_when_there_are_no_marks_it_raises(self):
        with self.assertRaises(ValueError):
            rosterkit.notices.absence_notice(student=STUDENT, marks=[])
